package com.nigson.integration.carrier;
import java.util.*;
import java.time.*;
import java.math.BigDecimal;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.*;
import com.nigson.integration.providers.*;
import com.nigson.shared.security.ProviderHttp;
import com.nigson.shared.events.EventCodec;
import tools.jackson.databind.JsonNode;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class PandagoBookingPersistenceTest {
 JdbcTemplate jdbc;TransactionTemplate tx;PandagoAdapter provider;GeocodingProvider geo;PandagoCommerceClient commerce;PandagoBookingWorker worker;UUID shipment,reference,generation;Instant source;Clock clock;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"isolated PostgreSQL qualification required");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("ISOLATED_DATABASE_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=integration","nigson_integration_app","mock-integration-runtime");jdbc=new JdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);tx=new TransactionTemplate(manager);provider=mock(PandagoAdapter.class);geo=mock(GeocodingProvider.class);commerce=mock(PandagoCommerceClient.class);shipment=UUID.randomUUID();reference=UUID.randomUUID();generation=UUID.randomUUID();clock=Clock.systemUTC();source=clock.instant();
  when(provider.mode()).thenReturn(ProviderHttp.Mode.MOCK);when(provider.accountFingerprint()).thenReturn("1".repeat(64));when(geo.resolve(any())).thenAnswer(call->{assertThat(TransactionSynchronizationManager.isActualTransactionActive()).isFalse();return new GeocodingProvider.Point(new BigDecimal("6.5"),new BigDecimal("3.4"));});
  when(provider.quote(any(),any())).thenAnswer(call->{assertThat(TransactionSynchronizationManager.isActualTransactionActive()).isFalse();return new PandagoAdapter.Quote("quote",BigDecimal.ONE,"NGN",clock.instant().plusSeconds(300),"1".repeat(64));});
  when(provider.confirm(any(),any(),any(),any(),any(),any(),any(),any())).thenAnswer(call->{assertThat(TransactionSynchronizationManager.isActualTransactionActive()).isFalse();return new PandagoAdapter.Order("stage-order",reference.toString(),"NEW");});
  when(commerce.context(shipment)).thenReturn(context("PAID",null));doAnswer(call->{assertThat(TransactionSynchronizationManager.isActualTransactionActive()).isFalse();return null;}).when(commerce).acknowledge(any(),any());
  worker=new PandagoBookingWorker(jdbc,manager,provider,geo,commerce,clock,generation,source.minusSeconds(5),source.plusSeconds(600),new io.micrometer.core.instrument.simple.SimpleMeterRegistry());intake();
 }
 JsonNode context(String method,Instant scheduled){var n=EventCodec.JSON.createObjectNode();n.put("shipmentId",shipment.toString());n.put("bookingReference",reference.toString());n.put("accountHash","1".repeat(64));n.put("mode","MOCK");n.put("amount","25.00");n.put("deliveryAmount","1.00");n.put("description","Synthetic checkout order");n.put("paymentMethod",method);n.put("pickupCode","7F3A9C21B4");if(scheduled==null)n.putNull("preorderedFor");else n.put("preorderedFor",scheduled.toString());var a=n.putObject("address");a.put("line1","Synthetic street");a.put("line2","2nd Floor, Door B - leave at the door");a.put("city","Lagos");a.put("region","Lagos");a.put("countryCode","NG");a.put("recipient","Synthetic recipient");a.put("phone","+2348000000001");return n;}
 void intake(){var e=EventCodec.JSON.valueToTree(Map.of("producer","commerce","event_type","shipment.booking.requested.v1","aggregate_id",shipment,"occurred_at",source,"payload",Map.of("shipment_id",shipment,"booking_request_id",reference,"provider","PANDAGO")));tx.executeWithoutResult(s->new PandagoBookingRequested(generation,source.minusSeconds(5),clock,"MOCK").handle(jdbc,e));}
 String state(){return jdbc.queryForObject("SELECT state FROM integration.carrier_booking WHERE shipment_id=?",String.class,shipment);}
 void due(){jdbc.update("UPDATE integration.carrier_booking SET next_poll_at=now() WHERE shipment_id=?",shipment);}
 @AfterEach void close(){if(jdbc!=null)jdbc.update("DELETE FROM integration.carrier_booking WHERE shipment_id=?",shipment);}
 @Test void duplicateEventsAndWorkerPollsBookOnceAndStoreProviderId(){intake();assertThat(worker.poll()).isEqualTo(1);assertThat(worker.poll()).isZero();assertThat(state()).isEqualTo("BOOKED");assertThat(jdbc.queryForObject("SELECT provider_shipment_id FROM integration.carrier_booking WHERE shipment_id=?",String.class,shipment)).isEqualTo("stage-order");verify(provider,times(1)).confirm(any(),eq(reference),argThat(r->r.notes().equals("2nd Floor, Door B - leave at the door")),eq(new BigDecimal("25.00")),any(),eq("PAID"),isNull(),eq("7F3A9C21B4"));verify(commerce).acknowledge(eq(shipment),argThat(n->n.path("reference").asString().equals("stage-order")&&n.path("bookingState").asString().equals("BOOKED")));}
 @Test void scheduledCashOnDeliveryUsesTheSameDurableBookingPath(){Instant scheduled=clock.instant().plusSeconds(7200);when(commerce.context(shipment)).thenReturn(context("CASH_ON_DELIVERY",scheduled));worker.poll();verify(provider).confirm(any(),eq(reference),argThat(r->r.notes().equals("2nd Floor, Door B - leave at the door")),any(),any(),eq("CASH_ON_DELIVERY"),eq(scheduled),eq("7F3A9C21B4"));assertThat(state()).isEqualTo("BOOKED");}
 @Test void timeoutAfterAcceptanceNeverCreatesAgain(){when(provider.confirm(any(),any(),any(),any(),any(),any(),any(),any())).thenThrow(new ProviderHttp.Failure("PANDAGO_RESPONSE_LOST",true,503));worker.poll();assertThat(state()).isEqualTo("UNKNOWN");due();worker.poll();verify(provider,times(1)).confirm(any(),any(),any(),any(),any(),any(),any(),any());assertThat(state()).isEqualTo("UNKNOWN");}
 @Test void expiredPreparedLeaseIsUnknownAndCannotCreate(){jdbc.update("UPDATE integration.carrier_booking SET state='CLAIMED',prepared_at=now(),account_hash=?,lease_until=now()-interval '1 second' WHERE shipment_id=?","1".repeat(64),shipment);worker.poll();assertThat(state()).isEqualTo("UNKNOWN");verify(provider,never()).confirm(any(),any(),any(),any(),any(),any(),any(),any());}
 @Test void responsePersistenceSurvivesCommerceAcknowledgementFailure(){doThrow(new IllegalStateException("SIMULATED_ACK_OUTAGE")).doNothing().when(commerce).acknowledge(any(),any());worker.poll();assertThat(state()).isEqualTo("BOOKED");due();worker.poll();assertThat(state()).isEqualTo("BOOKED");verify(provider,times(1)).confirm(any(),any(),any(),any(),any(),any(),any(),any());var captures=org.mockito.ArgumentCaptor.forClass(JsonNode.class);verify(commerce,times(2)).acknowledge(eq(shipment),captures.capture());assertThat(captures.getAllValues().get(0)).isEqualTo(captures.getAllValues().get(1));}
 @Test void changedQuoteFeeFailsWithoutCreatingAProviderOrder(){when(provider.quote(any(),any())).thenReturn(new PandagoAdapter.Quote("changed",new BigDecimal("2.00"),"NGN",clock.instant().plusSeconds(300),"1".repeat(64)));worker.poll();assertThat(state()).isEqualTo("FAILED");verify(provider,never()).confirm(any(),any(),any(),any(),any(),any(),any(),any());}
 @Test void missingPickupCodeFailsBeforeProviderConfirmation(){var c=context("PAID",null);((tools.jackson.databind.node.ObjectNode)c).remove("pickupCode");when(commerce.context(shipment)).thenReturn(c);worker.poll();assertThat(state()).isEqualTo("FAILED");verify(provider,never()).confirm(any(),any(),any(),any(),any(),any(),any(),any());}
 @Test void blankFloorDoorDetailsDoNotFallBackToOrderOrCustomerInformation(){var c=context("PAID",null);((tools.jackson.databind.node.ObjectNode)c.path("address")).put("line2","  ");when(commerce.context(shipment)).thenReturn(c);worker.poll();assertThat(state()).isEqualTo("BOOKED");verify(provider).confirm(any(),eq(reference),argThat(r->r.notes()==null&&!r.location().address().contains("Synthetic recipient")),any(),any(),any(),any(),eq("7F3A9C21B4"));}
 @Test void invalidPickupCodeCannotCreateAnOrder(){var c=context("PAID",null);((tools.jackson.databind.node.ObjectNode)c).put("pickupCode","bad code");when(commerce.context(shipment)).thenReturn(c);worker.poll();assertThat(state()).isEqualTo("FAILED");verify(provider,never()).confirm(any(),any(),any(),any(),any(),any(),any(),any());}
 @Test void restoredDifferentGenerationCannotCreate(){jdbc.update("UPDATE integration.carrier_booking SET creation_generation=? WHERE shipment_id=?",UUID.randomUUID(),shipment);worker.poll();assertThat(state()).isEqualTo("UNKNOWN");verify(provider,never()).confirm(any(),any(),any(),any(),any(),any(),any(),any());}
 @Test void quoteOutageBeforePreparationCanRetrySafely(){when(provider.quote(any(),any())).thenThrow(new ProviderHttp.Failure("PROVIDER_HTTP_503",true,503)).thenReturn(new PandagoAdapter.Quote("quote",BigDecimal.ONE,"NGN",clock.instant().plusSeconds(300),"1".repeat(64)));worker.poll();assertThat(state()).isEqualTo("PENDING");due();worker.poll();assertThat(state()).isEqualTo("BOOKED");verify(provider,times(1)).confirm(any(),any(),any(),any(),any(),any(),any(),any());}
 @Test void activeLeasePreventsConcurrentProviderCreation() throws Exception {var entered=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);when(provider.confirm(any(),any(),any(),any(),any(),any(),any(),any())).thenAnswer(call->{entered.countDown();assertThat(release.await(10,java.util.concurrent.TimeUnit.SECONDS)).isTrue();return new PandagoAdapter.Order("stage-order",reference.toString(),"NEW");});try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var first=pool.submit(()->worker.poll());assertThat(entered.await(10,java.util.concurrent.TimeUnit.SECONDS)).isTrue();try{assertThat(worker.poll()).isZero();}finally{release.countDown();}assertThat(first.get(10,java.util.concurrent.TimeUnit.SECONDS)).isEqualTo(1);}verify(provider,times(1)).confirm(any(),any(),any(),any(),any(),any(),any(),any());assertThat(state()).isEqualTo("BOOKED");}

}
